-- Add SAM 2, introduced in arXiv 2408.00714.
-- Added 2026-10-18 from a scan of methods named by many recent papers but
-- missing from the catalog. The source paper gets the source evidence row (Introduced banner).

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'sam-2',
    'SAM 2',
    'Segment Anything Model 2 (SAM 2)',
    'SAM 2 (Segment Anything Model 2) extends [Segment Anything](/methods/segment-anything-sam) from images to videos as a foundation model for promptable visual segmentation. Given clicks, boxes or masks on any frame, it segments the target object and tracks it through the video. The architecture is a simple [Transformer](/methods/transformer) with streaming memory: an image encoder processes frames one at a time, memory attention conditions the current frame on a memory bank of past predictions and prompts, and a mask decoder produces the masklet, which allows real-time processing; on single images it reduces to SAM. A model-in-the-loop data engine produced SA-V, with 35.5M masks across 50.9K videos. In video segmentation SAM 2 is more accurate while using 3x fewer interactions than prior approaches, and on images it is more accurate and 6x faster than the original SAM. Its successor is [SAM 3](/methods/sam-3).',
    'SAM 2, SAM2, SAM-2, segment anything model 2, segment anything 2, segment anything v2',
    (
        SELECT id
        FROM areas
        WHERE name = 'Vision'
        LIMIT 1
    ),
    2024,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '2408.00714'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'SAM 2: Segment Anything in Images and Videos',
    'https://github.com/facebookresearch/sam2',
    NULL,
    '[SAM 2: Segment Anything in Images and Videos](/paper/2408.00714)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id FROM methods
WHERE slug = 'sam-2' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source' FROM methods
WHERE slug = 'sam-2' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

