INSERT INTO paper_method_exclusions (paper_id, method_id, reason)
SELECT paper_id, method_id, 'sam-2 citation review 2026-10-18: cites the source without naming the method in title or abstract'
FROM sam_2_excluded_papers
ON CONFLICT (paper_id, method_id) DO UPDATE SET
    reason = EXCLUDED.reason,
    updated_at = now();

DELETE FROM paper_methods pm
USING sam_2_excluded_papers x
WHERE pm.paper_id = x.paper_id AND pm.method_id = x.method_id;

-- 116 local citers name the method in title or abstract.
CREATE TEMP TABLE sam_2_cited_papers ON COMMIT DROP AS
SELECT p.id AS paper_id, m.id AS method_id
FROM papers p
CROSS JOIN methods m
WHERE m.slug = 'sam-2'
  AND p.id IS DISTINCT FROM m.source_paper_id
  AND p.id IN (
        35452, 35462, 35507, 35601, 35605, 35670, 35853, 36393, 37287, 38947, 39051, 40135,
        40525, 40532, 40642, 42588, 42790, 42856, 44174, 45421, 45759, 46729, 46809, 46922,
        47298, 47341, 47636, 47783, 48334, 48688, 49977, 50374, 50645, 50655, 50891, 51421,
        51557, 51564, 51587, 51683, 52018, 52269, 52539, 53757, 54230, 54535, 54655, 54738,
        55270, 55449, 55457, 56109, 56951, 59482, 62480, 62490, 64585, 66076, 66224, 66922,
        68057, 68364, 68384, 68483, 69848, 70185, 70527, 71806, 71820, 72065, 72857, 74277,
        75036, 75662, 75711, 76281, 83315, 83607, 83997, 84283, 85155, 85349, 85442, 86170,
        86216, 86261, 88015, 88180, 88183, 89930, 94654, 94835, 95921, 97295, 98981, 101573,
